package org.jkiss.dbeaver.teststudio.core;
import com.google.gson.*;import java.nio.charset.StandardCharsets;import org.jkiss.dbeaver.teststudio.spi.TestReportProvider;
final class JUnitReportProvider implements TestReportProvider{public String format(){return "junit";}public String extension(){return "xml";}public byte[] generate(JsonObject run,JsonObject options){JsonArray steps=StudioJson.array(run,"steps");int failures=0,errors=0,skipped=0;StringBuilder body=new StringBuilder();for(JsonElement e:steps){JsonObject s=e.getAsJsonObject();String name=esc(StudioJson.string(s,"name",StudioJson.string(s,"id","step")));String time=String.format(java.util.Locale.ROOT,"%.3f",s.has("elapsed_ms")?s.get("elapsed_ms").getAsDouble()/1000.0:0);body.append("  <testcase name=\"").append(name).append("\" time=\"").append(time).append("\">");String status=StudioJson.string(s,"status",StudioJson.bool(s,"passed",false)?"passed":"failed");if(status.equals("skipped")||status.equals("unsupported")){skipped++;body.append("<skipped message=\"").append(esc(StudioJson.string(s,"message",status))).append("\"/>");}else if(s.has("error")){errors++;body.append("<error message=\"").append(esc(StudioJson.string(s,"error","error"))).append("\"/>");}else if(!StudioJson.bool(s,"passed",false)){failures++;body.append("<failure message=\"").append(esc(StudioJson.string(s,"message","assertion failed"))).append("\">").append(esc(StudioJson.GSON.toJson(s))).append("</failure>");}body.append("</testcase>\n");}String suite=esc(StudioJson.string(run,"name",StudioJson.string(run,"plan_id","Test Studio")));String xml="<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<testsuite name=\""+suite+"\" tests=\""+steps.size()+"\" failures=\""+failures+"\" errors=\""+errors+"\" skipped=\""+skipped+"\">\n"+body+"</testsuite>\n";return xml.getBytes(StandardCharsets.UTF_8);}private static String esc(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}}
